import hashlib, random

TOMB = "DEL"

class Bloom:
    def __init__(self, items, bits_per_key=10, k=4):
        self.n, self.k = max(8, len(items) * bits_per_key), k
        self.bits = bytearray(self.n)
        for key in items:
            for i in self._idx(key):
                self.bits[i] = 1
    def _idx(self, key):
        d = hashlib.md5(key.encode()).digest()
        return [int.from_bytes(d[4 * i:4 * i + 4], "big") % self.n for i in range(self.k)]
    def might_contain(self, key):
        return all(self.bits[i] for i in self._idx(key))

class SSTable:                      # immutable, sorted by key
    def __init__(self, data):
        self.rows = dict(sorted(data.items()))
        self.bloom = Bloom(self.rows)
        self.lo, self.hi = min(self.rows), max(self.rows)

class LSM:
    def __init__(self, memtable_limit=100, fanout=4, use_bloom=True):
        self.mem, self.levels = {}, [[]]
        self.limit, self.fanout, self.use_bloom = memtable_limit, fanout, use_bloom
        self.user_writes = self.rows_written = self.probes = 0

    def put(self, key, value):          # real systems append to a WAL first
        self.mem[key] = value
        self.user_writes += 1
        if len(self.mem) >= self.limit:
            self.flush()

    def delete(self, key):
        self.put(key, TOMB)

    def flush(self):
        if not self.mem:
            return
        self.levels[0].insert(0, SSTable(self.mem))     # newest first
        self.rows_written += len(self.mem)
        self.mem = {}
        for lvl in range(len(self.levels)):             # size-tiered compaction
            if len(self.levels[lvl]) < self.fanout:
                break
            merged = {}
            for t in reversed(self.levels[lvl]):        # oldest first, newest wins
                merged.update(t.rows)
            self.levels[lvl] = []
            if lvl + 1 == len(self.levels):
                self.levels.append([])
                merged = {k: v for k, v in merged.items() if v != TOMB}   # bottom: drop tombstones
            if merged:
                self.levels[lvl + 1].insert(0, SSTable(merged))
                self.rows_written += len(merged)

    def get(self, key):
        if key in self.mem:
            v = self.mem[key]
            return None if v == TOMB else v
        for lvl in self.levels:
            for t in lvl:
                if self.use_bloom and not t.bloom.might_contain(key):
                    continue
                self.probes += 1
        if key in t.rows:
            v = t.rows[key]
            return None if v == TOMB else v
return None

public List<Order> latestOrders(String customerId, int n) {
    QueryConditional key = QueryConditional.keyEqualTo(Key.builder()
            .partitionValue(customerId).build());
    QueryEnhancedRequest request = QueryEnhancedRequest.builder()
            .queryConditional(key)
            .scanIndexForward(false)          // newest first: descending sort key
            .limit(n)
            .build();
    return table.query(request).items().stream().limit(n).toList();
}

public void markShipped(String customerId, String orderTsId) {
    Expression expected = Expression.builder()
            .expression("#s = :placed")
            .putExpressionName("#s", "status")
            .putExpressionValue(":placed", AttributeValue.fromS("PLACED"))
            .build();
    UpdateItemEnhancedRequest<Order> req = UpdateItemEnhancedRequest.builder(Order.class)
            .item(new Order(customerId, orderTsId, "SHIPPED"))
            .conditionExpression(expected)     // optimistic concurrency, fails if not PLACED
            .build();
    table.updateItem(req);
}

