import math, re
from collections import defaultdict

DOCS = {
    1: "PostgreSQL is a relational database with strong transactional guarantees",
    2: "Cassandra is a wide column database designed for write heavy workloads",
    3: "Elasticsearch builds an inverted index for full text search",
    4: "An inverted index maps each term to the documents containing the term",
    5: "Relational databases use B-tree indexes while Cassandra uses LSM trees",
    6: "Full text search ranks documents by relevance using BM25",
    7: "Redis is an in-memory key value store",
}
STOP = {"is", "a", "an", "for", "the", "to", "each", "by", "while", "with", "using", "in"}

def analyze(text):
    toks = re.findall(r"[a-z0-9]+", text.lower())
    out = []
    for t in toks:
        if t in STOP: continue
        if t.endswith("xes"): t = t[:-2]                       # indexes -> index
        elif t.endswith("ed") and len(t) > 5: t = t[:-2]       # inverted -> invert
        elif t.endswith("ing") and len(t) > 6: t = t[:-3]      # containing -> contain
        elif t.endswith("s") and not t.endswith("ss"): t = t[:-1]
        out.append(t)
    return out

index = defaultdict(dict)       # term -> {doc_id: term frequency}
length = {}
for d, text in DOCS.items():
    toks = analyze(text); length[d] = len(toks)
    for t in toks: index[t][d] = index[t].get(d, 0) + 1
avg = sum(length.values()) / len(length); N = len(DOCS)

def bm25(query, k1=1.2, b=0.75):
    score = defaultdict(float)
    for t in analyze(query):
        post = index.get(t, {})
        idf = math.log(1 + (N - len(post) + 0.5) / (len(post) + 0.5))
        for d, tf in post.items():
            score[d] += idf * tf * (k1 + 1) / (tf + k1 * (1 - b + b * length[d] / avg))
    return sorted(score.items(), key=lambda x: -x[1])

for term in ("index", "invert", "cassandra", "search", "relational"):
    print("%-10s -> %s" % (term, dict(sorted(index[term].items()))))
print("terms:", len(index), "docs:", N, "avg length: %.2f" % avg)
for q in ("inverted index", "cassandra write", "full text search relevance"):
    print(repr(q), [(d, round(s, 2)) for d, s in bm25(q)])
