public class OrderCrud {
    public static void main(String[] args) {
        try (MongoClient client = MongoClients.create("mongodb://127.0.0.1:27017")) {
            MongoCollection<Document> orders = client.getDatabase("shop")
                .getCollection("orders")
                .withWriteConcern(WriteConcern.MAJORITY);   // explicit: durable across failover

            // Filtered positional update (arrayFilters)
            UpdateResult r = orders.updateOne(
                eq("_id", 3),
                combine(set("items.$[l].qty", 4), inc("totalCents", 499)),
                new UpdateOptions().arrayFilters(List.of(eq("l.sku", "P0041"))));
            System.out.println("matched=" + r.getMatchedCount()
                + " modified=" + r.getModifiedCount());

            // Atomic claim of the oldest pending order
            Document claimed = orders.findOneAndUpdate(
                eq("status", "pending"),
                set("status", "paid"),
                new FindOneAndUpdateOptions().sort(Sorts.ascending("placedAt"))
                    .returnDocument(ReturnDocument.AFTER));
            System.out.println(claimed);

            // Unordered bulk: continue past individual failures
            List<WriteModel<Document>> ops = List.of(
                new UpdateOneModel<>(eq("_id", 1), set("status", "shipped")),
                new UpdateOneModel<>(eq("_id", 5), push("tags", "fragile")),
                new DeleteOneModel<>(eq("_id", 4)));
            System.out.println(orders.bulkWrite(ops, new BulkWriteOptions().ordered(false)));
        }
    }
}

