public class PlaceOrder {
    public static void main(String[] args) {
        try (MongoClient client = MongoClients.create(
                "mongodb://db1:27017,db2:27017,db3:27017/shop?replicaSet=rs0&w=majority")) {
            MongoCollection<Document> orders = client.getDatabase("shop").getCollection("orders");
            MongoCollection<Document> stock = client.getDatabase("shop").getCollection("stock");

            TransactionOptions options = TransactionOptions.builder()
                    .readConcern(ReadConcern.SNAPSHOT)
                    .writeConcern(WriteConcern.MAJORITY)
                    .build();

            try (ClientSession session = client.startSession()) {
                String result = session.withTransaction(() -> {
                    UpdateResult r = stock.updateOne(session,
                            Filters.and(Filters.eq("sku", "A-100"), Filters.gte("qty", 2)),
                            Updates.inc("qty", -2));
                    if (r.getModifiedCount() == 0) {
                        throw new IllegalStateException("insufficient stock");
                    }
                    orders.insertOne(session, new Document("_id", 1001).append("status", "NEW"));
                    return "ordered";
                }, options);
                System.out.println(result);
            }
        }
    }
}

