import java.math.BigDecimal;
import java.util.List;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.mongodb.core.query.Criteria;
import org.springframework.data.mongodb.core.query.Query;
import org.springframework.data.mongodb.core.query.Update;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderService {

    private final OrderRepository orders;
    private final MongoTemplate template;

    public OrderService(OrderRepository orders, MongoTemplate template) {
        this.orders = orders;
        this.template = template;
    }

    public static class OutOfStockException extends RuntimeException {
        public OutOfStockException(String sku) { super("insufficient stock for " + sku); }
    }

    @Transactional
    public Order placeOrder(long customerId, String customerName, List<Order.Item> items) {
        BigDecimal total = BigDecimal.ZERO;
        for (Order.Item item : items) {
            Query q = new Query(Criteria.where("sku").is(item.sku()).and("qty").gte(item.qty()));
            var result = template.updateFirst(q, new Update().inc("qty", -item.qty()), "stock");
            if (result.getModifiedCount() == 0) {
                throw new OutOfStockException(item.sku());       // RuntimeException: abort
            }
            total = total.add(item.unitPrice().multiply(BigDecimal.valueOf(item.qty())));
        }
        Order order = new Order();
        order.setCustomerId(customerId);
        order.setCustomerName(customerName);
        order.getItems().addAll(items);
        order.setTotal(total);
        return orders.save(order);
    }

    @Transactional
    public void markPaid(String orderId) {
        Query q = new Query(Criteria.where("_id").is(orderId).and("status").is(Order.Status.NEW));
        Update paid = new Update().set("status", Order.Status.PAID);
        var result = template.updateFirst(q, paid, Order.class);
        if (result.getModifiedCount() == 0) {
            throw new IllegalStateException("order not found or not in state NEW: " + orderId);
        }
    }
}

