@RestController
@RequestMapping("/orders")
public class OrderController {

    public record ItemDto(@NotBlank String sku, @NotBlank String name, @Min(1) int qty,
                          BigDecimal unitPrice) {}
    public record PlaceOrderRequest(long customerId, @NotBlank String customerName,
                                    @NotEmpty List<@Valid ItemDto> items) {}

    private final OrderService service;

    public OrderController(OrderService service) { this.service = service; }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public String place(@Valid @RequestBody PlaceOrderRequest req) {
        List<Order.Item> items = req.items().stream()
                .map(i -> new Order.Item(i.sku(), i.name(), i.qty(), i.unitPrice())).toList();
        return service.placeOrder(req.customerId(), req.customerName(), items).getId();
    }

    @ExceptionHandler(OrderService.OutOfStockException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public String outOfStock(OrderService.OutOfStockException e) { return e.getMessage(); }
}

