@Service
public class OrderPlacement {

    private final JdbcTemplate jdbc;
    private final ObjectMapper json;

    public OrderPlacement(JdbcTemplate jdbc, ObjectMapper json) {
        this.jdbc = jdbc;
        this.json = json;
    }

    @Transactional
    public long place(long customerId, List<Line> lines) throws JsonProcessingException {
        Long orderId = jdbc.queryForObject(
            "INSERT INTO orders (customer_id, status, created_at) "
          + "VALUES (?, 'NEW', now()) RETURNING id",
            Long.class, customerId);
        for (int i = 0; i < lines.size(); i++) {
            Line l = lines.get(i);
            jdbc.update("INSERT INTO order_items (order_id, line_no, product_id, qty, unit_price) "
                      + "VALUES (?, ?, ?, ?, ?)",
                      orderId, i + 1, l.productId(), l.qty(), l.unitPrice());
            int changed = jdbc.update("UPDATE stock SET qty = qty - ? WHERE sku = ? AND qty >= ?",
                                      l.qty(), l.sku(), l.qty());
            if (changed == 0) {
                throw new IllegalStateException("insufficient stock for " + l.sku());
            }
        }
        String payload = json.writeValueAsString(Map.of("orderId", orderId, "lines", lines.size()));
        jdbc.update("INSERT INTO outbox (aggregate_id, type, payload) "
                  + "VALUES (?, 'OrderPlaced', ?::jsonb)", orderId, payload);
        return orderId;
    }

    public record Line(long productId, String sku, int qty, java.math.BigDecimal unitPrice) {}
}

@Scheduled(fixedDelay = 500)
public void publish() {
    List<OutboxRow> rows = jdbc.query(
        "SELECT id, aggregate_id, payload FROM outbox WHERE published_at IS NULL "
      + "ORDER BY id LIMIT 100 FOR UPDATE SKIP LOCKED", mapper);
    for (OutboxRow row : rows) {
        events.replaceOne(Filters.eq("_id", row.id()), Document.parse(row.payload())
                .append("_id", row.id()), new ReplaceOptions().upsert(true));   // idempotent
        jdbc.update("UPDATE outbox SET published_at = now() WHERE id = ?", row.id());
    }
}
